function login(err=''){app.innerHTML=`<div class="login-page"><section class="card login">${brand()}<div class="eyebrow">Área administrativa</div><h1>Bom te ver por aqui.</h1><p class="subhead">Entre para acompanhar os pedidos e organizar a operação da BomVizinho.</p>${err?`<p class="error">${esc(err)}</p>`:''}<form id="login"><label class="field">E-mail administrativo<input name="email" type="email" autocomplete="username" required></label><label class="field">Senha<input name="password" type="password" autocomplete="current-password" required></label><label class="remember-login"><input name="remember" type="checkbox" checked> Manter conectado neste dispositivo</label><button id="go">Entrar no painel</button></form><p class="muted" style="margin-top:20px;text-align:center">Acesso restrito à equipe BomVizinho</p></section></div>`;$('#login').onsubmit=async e=>{e.preventDefault();const b=$('#go');b.disabled=true;b.textContent='Entrando…';try{await api('/admin/login',{method:'POST',body:JSON.stringify({email:e.target.email.value,password:e.target.password.value,remember:!!e.target.remember?.checked})});await render()}catch(x){login(x.message==='credenciais_invalidas'?'E-mail ou senha incorretos.':x.message)}finally{if($('#go')){b.disabled=false;b.textContent='Entrar no painel'}}}}
