async function detail(id){const d=$('#detail');if(!d)return;d.innerHTML='<div class="modal-backdrop order-detail-backdrop" role="presentation"><section class="card detail-card order-detail-modal" role="dialog" aria-modal="true" aria-label="Detalhes do pedido">Carregando pedido…</section></div>';try{const x=await api('/admin/orders/'+encodeURIComponent(id)),o=x.order;d.innerHTML=`<div class="modal-backdrop order-detail-backdrop" role="presentation"><section class="card detail-card order-detail-modal" role="dialog" aria-modal="true" aria-labelledby="order-detail-title"><div class="od-head"><div><div class="eyebrow">DETALHES DO PEDIDO</div><h2 id="order-detail-title">Pedido #${esc(o.code)}</h2><div class="od-sub"><span class="pill">${esc(statuses[o.status]||o.status)}</span><small>${dt(o.created_at)}</small></div></div><button id="close" class="secondary od-close" type="button" aria-label="Fechar">✕</button></div>
<div class="od-total"><span>Total do pedido</span><b>${brl(o.total_cents??((o.subtotal_cents||0)+(o.shipping_cents||0)))}</b><small>${x.items.length} produto(s) · ${x.items.reduce((n,i)=>n+Number(i.quantity||0),0)} unidade(s)</small></div>
<section class="od-card"><h3><span class="od-n">1</span> Cliente</h3><b class="od-big">${esc(o.customer_name)}</b><p>${esc(o.customer_phone)}<br>${esc(o.customer_email||"E-mail não informado")}</p>${o.customer_note?`<div class="od-note"><small>Observação do cliente</small>${esc(o.customer_note)}</div>`:""}</section>
<section class="od-card"><h3><span class="od-n">2</span> Entrega e pagamento</h3><p><b>${esc(o.delivery_type)}</b>${o.street?`<br>${esc(o.street)}, ${esc(o.street_number)} ${esc(o.complement)}<br>${esc(o.district)} · ${esc(o.city)}/${esc(o.state)} · CEP ${esc(o.postal_code)}`:''}</p><p class="od-pay">Pagamento: <b>${esc(o.payment_method)}</b></p></section>
<section class="od-card"><h3><span class="od-n">3</span> Produtos do pedido</h3><ul class="od-items">${x.items.map(i=>`<li><img src="${bvImg(i.image_url,i.product_id)}" alt="" loading="lazy" onerror="bvImgErr(this)"><div><b>${esc(i.product_name)}</b><small>${i.quantity} × ${brl(i.unit_price_cents)}</small>${i.note?`<small class="od-item-note">Obs.: ${esc(i.note)}</small>`:''}</div><strong>${brl(i.subtotal_cents)}</strong></li>`).join('')}</ul><div class="od-sum"><div><span>Produtos</span><b>${brl(o.subtotal_cents)}</b></div><div><span>Frete</span><b>${o.shipping_cents==null?'A combinar':brl(o.shipping_cents)}</b></div></div></section>
<section class="od-card od-wa"><h3><span class="od-n">4</span> Falar com o cliente</h3><p>Escolha o assunto. A mensagem já vai pronta para você revisar e enviar pelo WhatsApp.</p><div class="order-wa-buttons"><button type="button" class="primary" data-wa-kind="address">Confirmar endereço</button><button type="button" class="secondary" data-wa-kind="data">Conferir dados</button><button type="button" class="secondary" data-wa-kind="order">Atualizar sobre o pedido</button></div></section>
<section class="od-card od-update"><h3><span class="od-n">5</span> Atualizar andamento</h3><label class="field">Em que etapa está?<select id="newstatus">${Object.entries(statuses).map(([v,t])=>`<option value="${v}" ${o.status===v?'selected':''}>${t}</option>`).join('')}</select></label><label class="field">Observação (opcional)<input id="note" maxlength="500" placeholder="Ex.: aguardando confirmação do cliente"></label><button id="save" type="button">Salvar atualização</button></section>
<section class="od-card"><h3><span class="od-n">6</span> Histórico</h3>${x.history.length?x.history.map(h=>`<div class="history"><b>${esc(h.event_type)}</b> <span class="muted">${dt(h.created_at)}</span><div>${esc(h.detail||'')}</div></div>`).join(''):'<p class="muted">Ainda não há atualizações no histórico.</p>'}</section></section></div>`;const closeDetail=()=>{d.innerHTML='';document.body.classList.remove('modal-open')};$('#close').onclick=closeDetail;const backdrop=d.querySelector('.order-detail-backdrop');backdrop.onclick=e=>{if(e.target===backdrop)closeDetail()};d.querySelectorAll('[data-wa-kind]').forEach(btn=>btn.onclick=()=>{const kind=btn.dataset.waKind;const phone=String(o.customer_phone||'').replace(/\D/g,'');if(!phone){alert('Este pedido não tem um telefone válido cadastrado.');return}const waPhone=phone.startsWith('55')?phone:'55'+phone;const address=[o.street,o.street_number,o.complement,o.district,o.city,o.state,o.postal_code].filter(Boolean).join(', ');const first=String(o.customer_name||'').trim().split(/\s+/)[0]||'tudo bem';const messages={address:`Olá, ${first}! Aqui é da BomVizinho. Você pode confirmar se o endereço do seu pedido #${o.code} está certinho?\n\n${address||'Ainda precisamos confirmar o endereço.'}\n\nSe precisar corrigir alguma informação, pode me mandar por aqui, por favor.`,data:`Olá, ${first}! Aqui é da BomVizinho. Pode conferir se seus dados do pedido #${o.code} estão corretos?\n\nNome: ${o.customer_name||'—'}\nTelefone: ${o.customer_phone||'—'}\nE-mail: ${o.customer_email||'Não informado'}\n\nSe tiver algo para corrigir, é só me avisar por aqui.`,order:`Olá, ${first}! Passando para atualizar você sobre o pedido #${o.code} da BomVizinho.\n\nStatus atual: ${statuses[o.status]||o.status}.\n\nSe tiver alguma dúvida, pode responder por aqui.`};window.open('https://wa.me/'+waPhone+'?text='+encodeURIComponent(messages[kind]),'_blank','noopener')});document.body.classList.add('modal-open');$('#save').onclick=async()=>{const b=$('#save');b.disabled=true;b.textContent='Salvando…';try{await api('/admin/orders/'+encodeURIComponent(id)+'/status',{method:'PATCH',body:JSON.stringify({status:$('#newstatus').value,version:o.version,note:$('#note').value})});await load(true);await detail(id)}catch(e){alert('Não foi possível salvar: '+e.message)}finally{if($('#save')){b.disabled=false;b.textContent='Salvar atualização'}}};d.scrollIntoView({behavior:'smooth',block:'start'})}catch(e){d.innerHTML=`<section class="card error">${esc(e.message)}</section>`}}
function closeDeleteModal(){const area=$('#delete-area');if(area)area.innerHTML='';deleteRange=null;document.body.classList.remove('modal-open')}
function deleteDialog(){const area=$('#delete-area');if(!area)return;document.body.classList.add('modal-open');area.innerHTML=`<div class="modal-backdrop" role="presentation"><section class="delete-modal" role="dialog" aria-modal="true" aria-labelledby="delete-title"><button class="modal-x" id="cancel-delete-x" aria-label="Fechar">×</button><div class="modal-icon">⌫</div><p class="eyebrow">GESTÃO DO HISTÓRICO</p><h2 id="delete-title">Excluir pedidos por período</h2><p class="modal-copy">Escolha o intervalo de datas. Antes de excluir, você poderá revisar a seleção e confirmar a ação.</p><div class="date-fields"><label class="field">Data inicial<input id="delete-from" type="date" required></label><label class="field">Data final<input id="delete-to" type="date" required></label></div><div class="delete-note"><b>Importante</b><p>Os pedidos desse período, incluindo itens e atualizações, serão removidos permanentemente. Essa ação não pode ser desfeita.</p></div><div class="modal-actions"><button id="cancel-delete" class="secondary">Cancelar</button><button id="review-delete" class="danger">Revisar exclusão</button></div></section></div>`;$('#cancel-delete').onclick=closeDeleteModal;$('#cancel-delete-x').onclick=closeDeleteModal;$('#review-delete').onclick=()=>{const from=$('#delete-from').value,to=$('#delete-to').value;if(!from||!to||from>to){$('#delete-date-error')?.remove();$('#review-delete').insertAdjacentHTML('beforebegin','<p id="delete-date-error" class="error">Confira as datas e tente novamente.</p>');return}deleteRange={from,to};confirmDeleteStep2()};$('#delete-from').focus()}
function confirmDeleteStep2(){const area=$('#delete-area');area.innerHTML=`<div class="modal-backdrop"><section class="delete-modal" role="dialog" aria-modal="true" aria-labelledby="delete-review-title"><button class="modal-x" id="cancel-delete-x" aria-label="Fechar">×</button><div class="modal-icon warning-icon">!</div><p class="eyebrow">ETAPA 2 DE 3</p><h2 id="delete-review-title">Revise o período selecionado</h2><div class="period-review"><span>De <b>${esc(deleteRange.from)}</b></span><span>Até <b>${esc(deleteRange.to)}</b></span></div><div class="delete-note"><b>Exclusão permanente</b><p>Todos os pedidos registrados nessas datas, incluindo seus itens e histórico de alterações, serão apagados.</p></div><label class="field">Para continuar, digite <b>CONFIRMO A EXCLUSÃO</b><input id="delete-phrase" autocomplete="off" placeholder="Digite a frase acima"></label><div class="modal-actions"><button id="back-delete" class="secondary">Voltar</button><button id="next-delete" class="danger" disabled>Continuar</button></div></section></div>`;$('#delete-phrase').oninput=()=>$('#next-delete').disabled=$('#delete-phrase').value!=='CONFIRMO A EXCLUSÃO';$('#back-delete').onclick=deleteDialog;$('#cancel-delete-x').onclick=closeDeleteModal;$('#next-delete').onclick=confirmDeleteStep3}
function confirmDeleteStep3(){const area=$('#delete-area');area.innerHTML=`<div class="modal-backdrop"><section class="delete-modal" role="dialog" aria-modal="true" aria-labelledby="delete-final-title"><button class="modal-x" id="cancel-delete-x" aria-label="Fechar">×</button><div class="modal-icon warning-icon">!</div><p class="eyebrow">ETAPA 3 DE 3 · CONFIRMAÇÃO FINAL</p><h2 id="delete-final-title">Confirmar exclusão dos pedidos?</h2><p class="modal-copy">Período selecionado: <b>${esc(deleteRange.from)}</b> a <b>${esc(deleteRange.to)}</b>.</p><div class="delete-note"><b>Esta ação é definitiva.</b><p>Depois da exclusão, não será possível recuperar esses pedidos pelo painel.</p></div><label class="confirm-check"><input id="really-delete" type="checkbox"> Entendo que os pedidos serão excluídos permanentemente.</label><div class="modal-actions"><button id="cancel-final" class="secondary">Cancelar</button><button id="do-delete" class="danger" disabled>Excluir pedidos</button></div></section></div>`;$('#really-delete').onchange=()=>$('#do-delete').disabled=!$('#really-delete').checked;$('#cancel-final').onclick=closeDeleteModal;$('#cancel-delete-x').onclick=closeDeleteModal;$('#do-delete').onclick=performDelete}
async function performDelete(){const b=$('#do-delete');if(!deleteRange||!$('#really-delete')?.checked)return;const typed=b.textContent;b.disabled=true;b.textContent='Excluindo…';try{const result=await api('/admin/orders/delete-by-date',{method:'POST',body:JSON.stringify({from:deleteRange.from,to:deleteRange.to,confirmation:'CONFIRMO A EXCLUSÃO'})});alert(`Exclusão concluída. ${result.deleted} pedido(s) foram removidos permanentemente.`);deleteRange=null;closeDeleteModal();await load(true)}catch(e){alert('Não foi possível excluir: '+e.message);b.disabled=false;b.textContent=typed}}
window.addEventListener('scroll',()=>{if(activeTab!=='overview'&&!loading&&hasMore&&window.innerHeight+window.scrollY>=document.documentElement.scrollHeight-350)load()});
